={
  "messaging_product": "whatsapp",
  "to": "{{ 
  (() => {
    let p = String($('Intervalo entre mensagens1').first().json.whatsapp || "").replace(/\D/g, "");

    // prefixo internacional discado (00...) e 0 de operadora antes do DDD
    if (p.startsWith("00")) p = p.slice(2);
    if (p.startsWith("0") && p.length >= 11) p = p.slice(1);

    // Remove o 55 SEMPRE que for codigo de pais, pra reavaliar o local pela
    // mesma regra. Antes o codigo fazia "return" aqui sem tratar, entao um
    // celular antigo gravado como 5511 8765-4321 (12 digitos, sem o 9) saia
    // desse jeito e o Meta recusava - enquanto o MESMO numero sem o 55
    // recebia o 9 corretamente. O guard de tamanho protege o DDD 55
    // (Santa Maria/RS): 11 digitos comecando em 55 e DDD, nao codigo de pais.
    if (p.length >= 12 && p.startsWith("55")) p = p.slice(2);

    const ddd = p.slice(0, 2);
    const local = p.slice(2);

    // celular atual: DDD + 9 digitos comecando em 9
    if (local.length === 9 && local[0] === "9") return "55" + ddd + local;
    // celular antigo: DDD + 8 digitos comecando em 6-9 -> falta o 9
    if (local.length === 8 && /[6-9]/.test(local[0])) return "55" + ddd + "9" + local;
    // FIXO: DDD + 8 digitos comecando em 2-5 -> pode ter WhatsApp Business,
    // mas NAO leva o 9. Inserir o 9 aqui criava um celular de outra pessoa.
    if (local.length === 8 && /[2-5]/.test(local[0])) return "55" + ddd + local;

    // qualquer outra coisa é invalida - a query nao deveria ter deixado chegar
    // aqui; devolve vazio pro Meta recusar e a falha ficar visivel no log.
    return "";
  })()
}}",
  "type": "template",
  "template": {
    "name": "mensagem_1_sem_incorporadora",
    "language": { "code": "pt_PT" },
    "components": [
      {
        "type": "body",
        "parameters": {{ JSON.stringify([
  { "type": "text", "text": String($('Intervalo entre mensagens1').first().json.clientes || "") }
]) }}
      }
    ]
  }
}

